const envelope = $input.first().json;
if (!Array.isArray(envelope.items)) {
  throw new Error('Expected a Cloudbrowser list response with an items array.');
}
const known = new Set(['user','idle','created_paused','upstream','free_allowance_exhausted','payment_required','concurrency_limit']);
const routine = new Set(['user','idle','created_paused']);
const pauseReasons = {};
let pausing = 0;
let paused = 0;
let needsReview = 0;

for (const browser of envelope.items) {
  if (!browser || typeof browser.status !== 'string') {
    throw new Error('Each item needs a browser status.');
  }
  if (browser.status === 'pausing') pausing++;
  else if (browser.status === 'paused') paused++;
  else continue;
  const reason = known.has(browser.pauseReason) ? browser.pauseReason : 'unknown';
  pauseReasons[reason] = (pauseReasons[reason] ?? 0) + 1;
  if (!routine.has(reason)) needsReview++;
}
return [{
  json: {
    inspected: envelope.items.length,
    paused,
    pausing,
    needsReview,
    pauseReasons,
    hasAnotherPage: typeof envelope.nextCursor === 'string' && envelope.nextCursor.length > 0,
  },
}];
